/**
 * Render a block AST to semantic HTML.
 * @param {Block[]} blocks - Array of block nodes
 * @param {RenderOptions} [options] - Rendering options
 * @returns {string} HTML string
 */
export function renderHTML(blocks, options = {}) {
  const { scope = 'content' } = options;
  return blocks.map(block => renderBlock(block, scope)).join('\n');
}

function renderBlock(block, scope) {
  switch (block.type) {
    case 'paragraph':
      return `<p>${renderInline(block.children)}</p>`;
    case 'heading':
      const tag = `h${block.attrs.level}`;
      return `<${tag}>${renderInline(block.children)}</${tag}>`;
    default:
      return '';
  }
}

@layer components {
  ui-callout {
    display: block;
    padding: var(--space-md) var(--space-lg);
    border-inline-start: 4px solid var(--callout-color, var(--color-blue-500));
    background: var(--callout-bg, var(--color-blue-50));
    border-radius: var(--radius-md);
    margin-block: var(--space-lg);
  }

  ui-callout[data-variant="warning"] {
    --callout-color: var(--color-amber-500);
    --callout-bg: var(--color-amber-50);
  }

  ui-callout[data-variant="danger"] {
    --callout-color: var(--color-red-500);
    --callout-bg: var(--color-red-50);
  }
}

